  final class MiniMap extends View {private JSONObject map;private final Paint paint=new Paint(3);private final java.util.HashSet<String> pending=new java.util.HashSet<>();MiniMap(Context c){super(c);}void setMap(JSONObject data){map=data;invalidate();}protected void onDraw(Canvas c){super.onDraw(c);c.drawColor(Color.rgb(191,190,159));if(map==null)return;float w=(float)map.optDouble("width",0),h=(float)map.optDouble("height",0);if(w<=0||h<=0)return;float scale=Math.min(getWidth()/w,getHeight()/h);float ox=(getWidth()-w*scale)/2,oy=(getHeight()-h*scale)/2;c.save();c.clipRect(ox,oy,ox+w*scale,oy+h*scale);JSONArray tiles=map.optJSONArray("tiles");if(tiles!=null)for(int i=0;i<tiles.length();i++){JSONObject t=tiles.optJSONObject(i);if(t==null)continue;String url=t.optString("url");if(!url.startsWith(HOME+"assets-build/worldmap/"))continue;Bitmap bmp; synchronized(spriteCache){bmp=spriteCache.get(url);}if(bmp==null){loadTile(url);continue;}float x=(float)t.optDouble("x"),y=(float)t.optDouble("y"),tw=(float)t.optDouble("w"),th=(float)t.optDouble("h");paint.setColor(Color.WHITE);c.drawBitmap(bmp,null,new RectF(ox+x*scale,oy+y*scale,ox+(x+tw)*scale,oy+(y+th)*scale),paint);}JSONArray hints=map.optJSONArray("hints");if(hints!=null)for(int i=0;i<hints.length();i++){JSONObject hint=hints.optJSONObject(i);if(hint==null)continue;String css=hint.optString("image");java.util.regex.Matcher mm=java.util.regex.Pattern.compile("url\\([\"']?(.*?)[\"']?\\)").matcher(css);if(!mm.find())continue;String url=mm.group(1);if(url.startsWith("/"))url=HOME.substring(0,HOME.length()-1)+url;if(!url.startsWith(HOME+"assets-build/worldmap/"))continue;Bitmap bmp;synchronized(spriteCache){bmp=spriteCache.get(url);}if(bmp==null){loadTile(url);continue;}float[] pos=numbers(hint.optString("position")),sz=numbers(hint.optString("size"));if(sz[0]<=0||sz[1]<=0)continue;float x=(float)hint.optDouble("x"),y=(float)hint.optDouble("y"),hw=(float)hint.optDouble("w"),hh=(float)hint.optDouble("h"),sx=bmp.getWidth()/sz[0],sy=bmp.getHeight()/sz[1];int bx=Math.max(0,Math.round(-pos[0]*sx)),by=Math.max(0,Math.round(-pos[1]*sy)),bw=Math.min(bmp.getWidth()-bx,Math.max(1,Math.round(hw*sx))),bh=Math.min(bmp.getHeight()-by,Math.max(1,Math.round(hh*sy)));if(bw>0&&bh>0)c.drawBitmap(bmp,new android.graphics.Rect(bx,by,bx+bw,by+bh),new RectF(ox+x*scale,oy+y*scale,ox+(x+hw)*scale,oy+(y+hh)*scale),paint);}JSONObject me=map.optJSONObject("marker");if(me!=null){float x=(float)me.optDouble("x"),y=(float)me.optDouble("y"),mw=(float)me.optDouble("w"),mh=(float)me.optDouble("h");paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(Math.max(3,2*scale));paint.setColor(Color.RED);c.drawRect(ox+x*scale,oy+y*scale,ox+(x+mw)*scale,oy+(y+mh)*scale,paint);paint.setStyle(Paint.Style.FILL);}c.restore();}void loadTile(String url){synchronized(pending){if(!pending.add(url))return;}new Thread(()->{HttpURLConnection conn=null;try{conn=(HttpURLConnection)new URL(url).openConnection();conn.setInstanceFollowRedirects(false);conn.setConnectTimeout(5000);conn.setReadTimeout(5000);String cookie=CookieManager.getInstance().getCookie(HOME);if(cookie!=null)conn.setRequestProperty("Cookie",cookie);if(conn.getResponseCode()==200){Bitmap bmp=BitmapFactory.decodeStream(conn.getInputStream());if(bmp!=null){synchronized(spriteCache){spriteCache.put(url,bmp);}handler.post(this::invalidate);}}}catch(Exception ignored){}finally{if(conn!=null)conn.disconnect();synchronized(pending){pending.remove(url);}}},"jiva-map-tile").start();}}
  void saveFavorites(){getSharedPreferences("dashboard",MODE_PRIVATE).edit().putString("favorites",favorites.toString()).apply();spellKey="";render();}
  void closeEditor(LinearLayout panel){root.removeView(panel);editing=false;for(int i=0;i<root.getChildCount();i++)root.getChildAt(i).setVisibility(View.VISIBLE);render();}
  void editFavorites(){editing=true;JSONArray options=latest.optJSONArray("spells"),items=latest.optJSONArray("items");java.util.ArrayList<JSONObject> available=new java.util.ArrayList<>();if(tabMode.equals("Sorts")&&options!=null)for(int i=0;i<options.length();i++)if(options.optJSONObject(i)!=null)available.add(options.optJSONObject(i));if(tabMode.equals("Objets")&&items!=null)for(int i=0;i<items.length();i++)if(items.optJSONObject(i)!=null)available.add(items.optJSONObject(i));for(int i=0;i<root.getChildCount();i++)root.getChildAt(i).setVisibility(View.GONE);LinearLayout panel=new LinearLayout(getContext());panel.setOrientation(1);root.addView(panel,new LinearLayout.LayoutParams(-1,-1));TextView heading=label("RACCOURCIS FAVORIS",18,ink);panel.addView(heading);TextView hint=label(available.isEmpty()?"Aucun raccourci sur la barre actuelle. Affiche d’abord des sorts ou objets sur l’écran du jeu.":"Choisis parmi les éléments de la barre affichée dans le jeu.",12,muted);hint.setPadding(0,8,0,8);panel.addView(hint);ScrollView scroll=new ScrollView(getContext());panel.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout list=new LinearLayout(getContext());list.setOrientation(1);scroll.addView(list);java.util.ArrayList<android.widget.CheckBox> boxes=new java.util.ArrayList<>();for(JSONObject a:available){android.widget.CheckBox box=new android.widget.CheckBox(getContext());box.setText(a.optString("name"));box.setTextColor(ink);box.setTextSize(13);for(int j=0;j<favorites.length();j++){JSONObject f=favorites.optJSONObject(j);if(f!=null&&f.optString("name").equals(a.optString("name"))&&f.optString("type").equals(a.optString("type")))box.setChecked(true);}list.addView(box);boxes.add(box);}LinearLayout controls=new LinearLayout(getContext());panel.addView(controls);Button cancel=new Button(getContext());cancel.setText("Annuler");cancel.setAllCaps(false);cancel.setTextColor(ink);cancel.setBackground(shape(Color.rgb(245,242,220),Color.rgb(177,165,126)));cancel.setOnClickListener(v->closeEditor(panel));controls.addView(cancel,new LinearLayout.LayoutParams(0,-2,1));Button clear=new Button(getContext());clear.setText("Tout effacer");clear.setAllCaps(false);clear.setTextColor(ink);clear.setBackground(shape(Color.rgb(245,242,220),Color.rgb(177,165,126)));clear.setOnClickListener(v->{favorites=new JSONArray();closeEditor(panel);saveFavorites();});controls.addView(clear,new LinearLayout.LayoutParams(0,-2,1));Button save=new Button(getContext());save.setText("Enregistrer");save.setAllCaps(false);save.setTextColor(Color.WHITE);save.setBackground(shape(Color.rgb(220,108,29),Color.rgb(164,77,22)));save.setOnClickListener(v->{JSONArray next=new JSONArray();for(int i=0;i<available.size();i++)if(boxes.get(i).isChecked())next.put(available.get(i));for(int j=0;j<favorites.length();j++){JSONObject f=favorites.optJSONObject(j);boolean visible=false;if(f!=null)for(JSONObject a:available)if(a.optString("name").equals(f.optString("name"))&&a.optString("type").equals(f.optString("type")))visible=true;if(f!=null&&!visible)next.put(f);}favorites=next;closeEditor(panel);saveFavorites();});controls.addView(save,new LinearLayout.LayoutParams(0,-2,1));}

  void gameIcon(ImageView image,String asset){new Thread(()->{HttpURLConnection c=null;try{URL u=new URL(HOME+"assets-build/ui/"+asset);c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(5000);c.setReadTimeout(5000);String cookie=CookieManager.getInstance().getCookie(HOME);if(cookie!=null)c.setRequestProperty("Cookie",cookie);if(c.getResponseCode()==200){android.graphics.Bitmap bmp=BitmapFactory.decodeStream(c.getInputStream());if(bmp!=null)handler.post(()->image.setImageBitmap(bmp));}}catch(Exception ignored){}finally{if(c!=null)c.disconnect();}},"jiva-icon").start();}
