  void spellIcon(ImageView image,JSONObject spell){String css=spell.optString("image");java.util.regex.Matcher match=java.util.regex.Pattern.compile("url\\([\"']?(.*?)[\"']?\\)").matcher(css);if(!match.find())return;String path=match.group(1);if(path.startsWith("/"))path=HOME.substring(0,HOME.length()-1)+path;final String url=path;if(!url.startsWith(HOME+"assets-build/"))return;float[] pos=numbers(spell.optString("position")),size=numbers(spell.optString("size"));float w=(float)spell.optDouble("width",0),h=(float)spell.optDouble("height",0);if(size[0]<=0||size[1]<=0||w<=0||h<=0)return;new Thread(()->{try{Bitmap source; synchronized(spriteCache){source=spriteCache.get(url);}if(source==null){HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(5000);c.setReadTimeout(5000);String cookie=CookieManager.getInstance().getCookie(HOME);if(cookie!=null)c.setRequestProperty("Cookie",cookie);if(c.getResponseCode()!=200){c.disconnect();return;}source=BitmapFactory.decodeStream(c.getInputStream());c.disconnect();if(source==null)return;synchronized(spriteCache){spriteCache.put(url,source);}}float sx=source.getWidth()/size[0],sy=source.getHeight()/size[1];int x=Math.max(0,Math.round(-pos[0]*sx)),y=Math.max(0,Math.round(-pos[1]*sy));int cw=Math.min(source.getWidth()-x,Math.max(1,Math.round(w*sx))),ch=Math.min(source.getHeight()-y,Math.max(1,Math.round(h*sy)));if(cw>0&&ch>0){Bitmap icon=Bitmap.createBitmap(source,x,y,cw,ch);handler.post(()->image.setImageBitmap(icon));}}catch(Exception ignored){}},"jiva-spell-icon").start();}
