  void update(JSONObject d){latest=d;render();}
  void render(){if(body==null||editing)return;String hp=latest.optString("hp"),ap=latest.optString("ap"),mp=latest.optString("mp");boolean present=!hp.isEmpty(),combat=latest.optBoolean("combat");boolean combatStarted=combat&&!wasCombat;if(combatStarted)tabMode="Sorts";else if(!combat&&wasCombat)tabMode="Carte";wasCombat=combat;if(combatStarted&&game.getUrl()!=null&&game.getUrl().startsWith(HOME))game.evaluateJavascript("document.querySelector('[data-testid=shortcut-tab-spells]')?.click()",null);status.setText(present?(combat?"COMBAT":"EXPLORATION"):"EN ATTENTE DU JEU");hpText.setText(present?" "+hp.replace("Points de vie ","")+"   ":" —   ");apText.setText(present?" "+ap.replace("Points d'action : ","")+"   ":" —   ");mpText.setText(present?" "+mp.replace("Points de mouvement : ",""):" — ");String kamas=latest.optString("kamas");resourceText.setText(kamas.isEmpty()?"":kamas);
   for(int i=0;i<tabs.getChildCount();i++){LinearLayout t=(LinearLayout)tabs.getChildAt(i);boolean active=tabMode.equals(t.getTag());t.setBackground(shape(active?Color.rgb(220,108,29):Color.rgb(245,242,220),active?Color.rgb(164,77,22):Color.rgb(177,165,126)));((TextView)t.getChildAt(1)).setTextColor(active?Color.WHITE:ink);}boolean shortcutTab=tabMode.equals("Sorts")||tabMode.equals("Objets");bar.setVisibility(shortcutTab?View.VISIBLE:View.GONE);mapPanel.setVisibility(tabMode.equals("Carte")?View.VISIBLE:View.GONE);chatPanel.setVisibility(tabMode.equals("Chat")?View.VISIBLE:View.GONE);
   String type=tabMode.equals("Objets")?"item":"spell";JSONArray source=latest.optJSONArray(type.equals("item")?"items":"spells"),visible=new JSONArray();for(int i=0;i<favorites.length();i++){JSONObject f=favorites.optJSONObject(i);if(f==null||!type.equals(f.optString("type")))continue;JSONObject match=null;if(source!=null)for(int j=0;j<source.length();j++){JSONObject c=source.optJSONObject(j);if(c!=null&&c.optString("name").equals(f.optString("name")))match=c;}visible.put(match==null?f:match);}if(visible.length()==0&&source!=null)visible=source;rebuildSpells(visible);
   String key=present+":"+combat;if(!key.equals(actionKey)){actionKey=key;actions.removeAllViews();if(present&&combat)actionButton("Fin du tour / Prêt","end",null);}StringBuilder out=new StringBuilder();if(!present)out.append("Connecte-toi au jeu.");else{java.util.regex.Matcher life=java.util.regex.Pattern.compile("(\\d+)\\D+(\\d+)").matcher(hp);if(life.find()){int current=Integer.parseInt(life.group(1)),max=Integer.parseInt(life.group(2));if(max>0&&current*100/max<=35)out.append("⚠ Vie basse. ");}if(combat){float[] a=numbers(ap),m=numbers(mp);if(a[0]<=0&&m[0]>0)out.append("Plus de PA : déplacement possible selon les cases.");else if(a[0]<=0&&m[0]<=0)out.append("Plus de PA ni de PM : vérifie avant de terminer ton tour.");else out.append("Choisis un sort puis vise une case.");}else if(shortcutTab&&visible.length()==0)out.append("Ajoute d'abord des éléments à la barre du jeu, puis touche +.");}body.setText(out.toString());mapView.setMap(latest.optJSONObject("map"));JSONArray lines=latest.optJSONArray("messages");StringBuilder text=new StringBuilder();if(lines!=null)for(int i=0;i<lines.length();i++){if(i>0)text.append("\n\n");text.append(lines.optString(i));}chatText.setText(text.length()==0?"Aucun message récent.":text.toString());}

